girl=(x,y)=>`<g id="girl">${originalGirl(x,y)}</g>`;
let puzzle={player:[1,4],boxes:[[2,4],[3,2]],history:[],moves:0},met=false,walkFrame=0,unwrapped=false,letterOpen=false;
let lastVisualStage=-1;
const targets=[[4,4],[5,2]],same=(a,b)=>a[0]===b[0]&&a[1]===b[1];
const windGoal=[1,2,1],windInitial=[3,0,2];wind=[...windInitial];
let sound=false,audio;
function chime(win=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();[0,win?4:2,win?7:4].forEach((n,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.11;o.type='sine';o.frequency.value=440*2**(n/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.45);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.5)})}catch{}}
const soundButton=document.createElement('button');soundButton.id='sound';soundButton.className='text';soundButton.textContent='声音：关';soundButton.setAttribute('aria-pressed','false');document.querySelector('header').insertBefore(soundButton,document.querySelector('#restart'));soundButton.onclick=()=>{sound=!sound;soundButton.textContent='声音：'+(sound?'开':'关');soundButton.setAttribute('aria-pressed',sound);if(sound)chime()};
const motionOff=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function say(s){document.querySelector('#speech').textContent=s}
function progress(){return `<div class="journey" aria-label="旅程进度">${['认出你','遇见','水流','风','一起','到家'].map((s,i)=>`<span class="${i===stage?'current':i<stage?'complete':''}"><i>${i<stage?'✓':i+1}</i>${s}</span>`).join('')}</div>`}
function decorate(){const g=document.querySelector('.game');if(g)g.insertAdjacentHTML('afterbegin',progress());if(lastVisualStage!==stage){document.querySelector('#app').classList.remove('enter');void document.querySelector('#app').offsetWidth;document.querySelector('#app').classList.add('enter');lastVisualStage=stage}document.querySelector('#skip').textContent='预览下一幕 →';document.querySelector('#hint').textContent=stage===4?'两人横屏 · 左右各一位':'轻点场景探索 · 随时可看提示';document.querySelectorAll('.keys').forEach(k=>k.innerHTML=`<span class="key ${(stage>=3||(stage===2&&puzzleDone()))?'earned':''}">⚷</span><span class="key ${(stage>=4||(stage===3&&wind.every((v,i)=>v===windGoal[i])))?'earned':''}">⚷</span>`)}
function house(){return `<g transform="translate(735 135)"><rect width="156" height="172" rx="6" fill="#e8d9bb"/><path d="M-22 3l100-78L178 3" fill="#b58e7b"/><path d="M-13 0l90-65 91 65" fill="none" stroke="#d6b39d" stroke-width="5"/><rect x="51" y="91" width="53" height="81" rx="26" fill="#879679"/><rect x="15" y="34" width="34" height="38" rx="6" fill="#f5e2a2"/><path d="M32 35v37m-17-19h34" stroke="#c7b38a" stroke-width="3"/><circle cx="94" cy="138" r="3" fill="#ebd49e"/><path d="M-17 173h192" stroke="#afab8b" stroke-width="7"/></g>`}
function meeting(){shell('原来，你在这里。','轻点小路，走到长椅旁。',`<g transform="translate(610 245)"><path d="M-55 25H55M-55 10H55" stroke="#a28c6b" stroke-width="12"/><path d="M-43 25v30m86-30v30" stroke="#8c8064" stroke-width="7"/></g><g class="float"><text x="610" y="180" text-anchor="middle" font-size="22" fill="#b98178">♡</text></g>`,boy(240,280)+girl(630,245),met?'你来啦。陪我去一个地方吧，路上可能要你帮一点小忙。':'我就在前面。慢慢走，不用急。',met?btn('depart','走吧，陪你去 →','primary'):btn('meetHelp','我该怎么过去？','text'));if(met){document.querySelector('#depart').onclick=()=>{chime();next()};document.querySelector('#boy').setAttribute('transform','translate(335 -15)');return}let pos=240;const svg=document.querySelector('.scene svg');svg.style.cursor='pointer';svg.onclick=e=>{const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());const target=Math.min(575,Math.max(200,local.x));cancelAnimationFrame(walkFrame);let last=0;document.querySelector("#boy")?.classList.add("walking");function step(time){const dt=last?Math.min((time-last)/1000,.05):1/60;last=time;pos+=Math.sign(target-pos)*Math.min(250*dt,Math.abs(target-pos));document.querySelector('#boy')?.setAttribute('transform',`translate(${pos-240} ${-(pos-240)*.045})`);if(Math.abs(pos-target)>.1){walkFrame=requestAnimationFrame(step)}else{document.querySelector("#boy")?.classList.remove("walking");if(pos>530){met=true;chime();render()}}}walkFrame=requestAnimationFrame(step)};document.querySelector('#meetHelp').onclick=()=>say('轻点长椅旁边的地面，我会沿着小路走过去。')}
function puzzleDone(){return targets.every(t=>puzzle.boxes.some(b=>same(b,t)))}
function move(dx,dy){if(stage!==2||puzzleDone())return false;const p=puzzle.player,n=[p[0]+dx,p[1]+dy],wall=a=>a[0]<1||a[0]>5||a[1]<1||a[1]>4;if(wall(n))return false;const bi=puzzle.boxes.findIndex(b=>same(b,n)),after=[n[0]+dx,n[1]+dy];if(bi>=0&&(wall(after)||puzzle.boxes.some(b=>same(b,after)))){say('这边推不动。换个方向试试，走错也可以撤销。');return false}puzzle.history.push({player:[...p],boxes:puzzle.boxes.map(b=>[...b]),moves:puzzle.moves});puzzle.player=n;if(bi>=0)puzzle.boxes[bi]=after;puzzle.moves++;if(puzzleDone())chime(true);render();return true}
function waterPuzzle(){const done=puzzleDone(),size=51,x0=325,y0=83;let board='';for(let y=0;y<6;y++)for(let x=0;x<7;x++){const wall=x===0||x===6||y===0||y===5,isTarget=targets.some(t=>same(t,[x,y]));board+=`<rect x="${x0+x*size}" y="${y0+y*size}" width="49" height="49" rx="7" fill="${wall?'#99ad8c':isTarget?'#e9cc93':'#e9e3d1'}" stroke="${wall?'#8ea480':'#d9d0b8'}"/>${isTarget?`<circle cx="${x0+x*size+24}" cy="${y0+y*size+24}" r="13" fill="none" stroke="#b49a66" stroke-dasharray="3 3" stroke-width="2"/>`:''}`};puzzle.boxes.forEach((b,index)=>{const ok=targets.some(t=>same(t,b));board+=`<g data-motion="box${index}" transform="translate(${x0+b[0]*size+5} ${y0+b[1]*size+5})"><rect width="40" height="40" rx="5" fill="${ok?'#c0c69b':'#bb9a72'}" stroke="#8e7859" stroke-width="2"/><path d="M5 5l30 30m0-30L5 35" stroke="#8e7859" stroke-width="2"/></g>`});board+=`<g data-motion="puzzleActor" transform="translate(${x0+puzzle.player[0]*size+25} ${y0+puzzle.player[1]*size+20}) scale(.55)">${originalBoy(0,0)}</g>`;shell('借一点水流，往前走。','把两个木箱推到金色圆圈上，腾出水车的进水口。',`<path d="M0 255H325M680 255H1000" stroke="#9abfc0" stroke-width="48"/><path class="waterline" d="M0 247H325${done?'M680 247H1000':''}" stroke="#d8eeea" stroke-width="5" stroke-dasharray="20 13"/>${board}<g transform="translate(825 250)" class="${done?'wheel':''}"><circle r="49" fill="none" stroke="#8b9576" stroke-width="9"/><path d="M0-49v98m-49-49h98m-84-34 68 68m0-68-68 68" stroke="#8b9576" stroke-width="6"/></g>`,girl(180,280),done?'听，水车转起来了。第一把钥匙，收好啦。':'我在这里等你。箱子只能推，推错了可以退一步。',done?btn('continue','收好钥匙，继续走 →','primary'):`<div class="dpad">${btn('up','↑')}${btn('leftMove','←')}${btn('down','↓')}${btn('rightMove','→')}</div><div class="puzzle-tools"><span>已走 ${puzzle.moves} 步</span>${btn('undo','↶ 撤销','text')}${btn('retry','重摆木箱','text')}${btn('tip','一点提示','text')}</div>`);if(done){document.querySelector('#continue').onclick=next;return}const directions={up:[0,-1],leftMove:[-1,0],down:[0,1],rightMove:[1,0]};for(const [id,d]of Object.entries(directions))document.querySelector('#'+id).onclick=()=>move(...d);document.querySelector('#undo').disabled=!puzzle.history.length;document.querySelector('#undo').onclick=()=>{const prev=puzzle.history.pop();if(prev){Object.assign(puzzle,prev);render()}};document.querySelector('#retry').onclick=()=>{puzzle={player:[1,4],boxes:[[2,4],[3,2]],history:[],moves:0};render()};document.querySelector('#tip').onclick=()=>say('先把身边的箱子向右推两格。再绕到上面箱子的左边，也向右推两格。')}
function windPuzzle(){const done=wind.every((v,i)=>v===windGoal[i]);let fans='';const spots=[[350,175],[550,175],[550,295]];spots.forEach(([x,y],i)=>{fans+=`<g class="fan-hit" data-fan="${i}" role="button" tabindex="0" aria-label="转动第${i+1}个风向标" transform="translate(${x} ${y})"><circle r="51" fill="transparent"/><circle r="35" fill="#f5f0dc" stroke="#9ba98a" stroke-width="3"/><text y="12" text-anchor="middle" fill="#697f63" font-size="38">${['↑','→','↓','←'][wind[i]]}</text><text y="60" text-anchor="middle" fill="#7f8d74" font-size="12">${i+1}</text></g>`});shell('让风绕个弯，找到灯光。','轻点风向标，把风沿着虚线送到小屋。',`<path d="M180 175H550V295H745" fill="none" stroke="#edf2e6" stroke-width="23"/><path class="windline" d="M180 175H550V295H745" fill="none" stroke="#a6b8a0" stroke-width="2" stroke-dasharray="8 9"/><text x="160" y="180" font-size="24" fill="#748b70">→</text>${house()}${fans}<g class="mist" style="opacity:${done?0:.75}" fill="#f0f1e9"><ellipse cx="795" cy="220" rx="100" ry="60"/><ellipse cx="900" cy="265" rx="110" ry="70"/></g>`,boy(150,290)+girl(95,295),done?'风绕过了弯，灯亮了。我们离目的地越来越近啦。':'不是每阵风都要朝右。看一看，路在哪里转了个弯？',done?btn('continue','带上第二把钥匙 →','primary'):btn('windTip','看看提示','text'));if(done){document.querySelector('#continue').onclick=next;return}document.querySelectorAll('[data-fan]').forEach(el=>{const rotate=()=>{const i=Number(el.dataset.fan);wind[i]=(wind[i]+1)%4;if(wind.every((v,i)=>v===windGoal[i]))chime(true);render()};el.onclick=rotate;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();rotate()}}});document.querySelector('#windTip').onclick=()=>say('第一阵向右，第二阵向下，第三阵再向右。把风送到门口就好。')}
setupHold=function(){holding.clear();holdStart=0;let value=0,last=0;const pointerOwners=new Map();for(const id of ['left','right']){const el=document.querySelector('#'+id);el.setAttribute('aria-label',id==='left'?'玩家一按住机关':'玩家二按住前进');el.onpointerdown=e=>{e.preventDefault();if(pointerOwners.has(id))return;el.setPointerCapture(e.pointerId);pointerOwners.set(id,e.pointerId);holding.add(id);el.classList.add('active')};const release=e=>{if(pointerOwners.get(id)!==e.pointerId)return;pointerOwners.delete(id);holding.delete(id);el.classList.remove('active')};el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=release}function tick(t){if(stage!==4||!joined)return;const dt=last?Math.min(t-last,60):0;last=t;if(holding.size===2)value=Math.min(1,value+dt/(bridge?1800:3200));else value=Math.max(0,value-dt/1800);const pct=Math.round(value*100),p=document.querySelector('#progress');if(p){p.textContent=holding.size===2?(bridge?'门就要开了 · ':'正在过桥 · ')+pct+'%':'左右各按住一个按钮';p.style.setProperty('--fill',pct+'%')}if(!bridge){document.querySelector('#boy')?.setAttribute('transform',`translate(${value*290} 0)`);const svg=document.querySelector('.scene svg');let b=document.querySelector('#liveBridge');if(!b){b=document.createElementNS('http://www.w3.org/2000/svg','path');b.id='liveBridge';b.setAttribute('d','M370 330h230');b.setAttribute('stroke','#d5bc93');b.setAttribute('stroke-width','28');svg.insertBefore(b,svg.querySelector('#boy'))}b.style.opacity=value>0?1:0}else document.querySelector('.scene').style.setProperty('--door-glow',value);if(value>=1){holding.clear();chime(true);if(!bridge){bridge=true;render();say('你过来了。现在轮到你接我，我们一起去开门。')}else{opened=true;next()}return}frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)};
function ending(){if(!unwrapped){shell('我们到家了。','走了这么远，来拆开最后一个小包裹吧。',`<rect x="130" y="75" width="740" height="300" rx="12" fill="#e7dcc6"/><path d="M130 310h740" stroke="#c8b79a" stroke-width="3"/><rect x="170" y="105" width="130" height="105" rx="50" fill="#a4b7a3"/><path d="M235 105v105m-65-52h130" stroke="#e8ddc8" stroke-width="6"/><path d="M330 280h340m-315 0v70m290-70v70" stroke="#ae9170" stroke-width="14"/><g id="package" class="present"><rect x="455" y="208" width="91" height="69" rx="5" fill="#bb997e"/><path d="M500 208v69m-45-45h91" stroke="#f0d8b7" stroke-width="9"/><path d="M500 208q-45-39-34-9q8 10 34 9q41-33 34-10q-3 12-34 10" stroke="#ead0ae" fill="none" stroke-width="6"/></g>`,boy(370,270)+girl(620,270),'这个包裹，等你亲手打开。',btn('gift','拆开写着你名字的包裹 →','primary'));document.querySelector('#gift').onclick=()=>{unwrapped=true;chime(true);render()};document.querySelector('#package').onclick=document.querySelector('#gift').onclick;return}app.innerHTML=`<section class="end reveal"><div class="eyebrow">A LITTLE SOMETHING, JUST FOR YOU</div><div class="badge">生日快乐，我最喜欢的人。</div><div class="skincare" aria-label="护肤品礼盒示意"><div class="bottle tall"><span>DAILY<br>CARE</span></div><div class="bottle pump"><span>FOR<br>YOU</span></div><div class="jar"><span>with love</span></div><i class="spark one">✧</i><i class="spark two">✧</i></div><h1>新的一岁，也一起。</h1><div class="letter">今天陪你换了新发型，<br>还有一套护肤品，想现在交给你。<br><br>也要好好照顾自己。<br>当然，我也会一起。</div><p class="handoff">现在，把现实中的礼物递给他吧。</p>${btn('readLetter',letterOpen?'收起这封信':'还有几句话，想对你说','control')}${letterOpen?'<div class="personal-letter">谢谢你走过这段小小的路。<br>以后还有好多地方，想和你一起去。<br>今天先到这里，来抱一下吧。<br><small>—— 一直想黏着你的人</small></div>':''}<div class="end-actions">${btn('home','回到小镇坐一会儿','text')}${btn('again','重新出发 ↻','text')}</div><p class="previewnote">护肤品为示意图，之后可换成真实礼物照片。</p></section>`;document.querySelector('#readLetter').onclick=()=>{letterOpen=!letterOpen;render()};document.querySelector('#home').onclick=()=>{stage=1;met=true;render()};document.querySelector('#again').onclick=reset;decorate()}
render=function(){chapter.textContent=labels[stage];cancelAnimationFrame(frame);cancelAnimationFrame(walkFrame);holding.clear();if(stage===1)meeting();else if(stage===2)waterPuzzle();else if(stage===3)windPuzzle();else if(stage===5)ending();else if(stage===4)cooperativeScene();else originalRender();decorate();if(stage===0){const s=document.querySelector('.verify small');if(s)s.textContent='选出三样属于约会菜单的食物。';const verify=document.querySelector('#verify'),f=verify.onclick;verify.onclick=()=>{const before=stage;f();if(stage!==before)chime(true)};document.querySelector('#hint').textContent='优化预览版 · 建议平板横屏'}};
reset=function(){puzzle={player:[1,4],boxes:[[2,4],[3,2]],history:[],moves:0};met=false;unwrapped=false;letterOpen=false;originalReset();wind=[...windInitial]};
document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};
document.addEventListener('keydown',e=>{if(stage!==2||/INPUT|TEXTAREA/.test(e.target.tagName))return;const d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(d){e.preventDefault();move(...d)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){holding.clear();document.querySelectorAll('.hold').forEach(el=>el.classList.remove('active'))}});
render();





